<template>
  <view class="group-page" :style="$themeStyle"><view class="group-hero"><text class="group-en">BETTER TOGETHER</text><text class="group-title">一起拼，生活更有趣</text><text class="group-copy">邀请好友成团，精选好物低至 7 折</text><view class="faces"><text>野</text><text>山</text><text>＋</text></view></view>
    <view class="steps"><view><text>1</text><text>选择好物</text></view><i></i><view><text>2</text><text>发起拼团</text></view><i></i><view><text>3</text><text>邀请好友</text></view><i></i><view><text>4</text><text>拼团成功</text></view></view>
    <view class="between section-head"><view><text class="section-title">正在热拼</text><text class="section-en">Trending groups</text></view><text class="muted">已有 263 人成团</text></view>
    <view class="group-list"><view v-for="(item,i) in products.slice(1,6)" :key="item.id" class="group-item card"><view class="art group-art" :class="'art-'+item.tone" @tap="open(item.id)"><image v-if="item.image" class="product-image" :src="item.image" mode="aspectFill"/><text v-else class="art-icon">{{item.cover}}</text><text class="people">{{2+i%2}} 人团</text></view><view class="group-info"><text class="item-title">{{item.title}}</text><text class="item-sub">{{item.subtitle}}</text><view class="active-group"><view class="tiny-face">{{['陈','李','周','吴','沈'][i]}}</view><text>还差 1 人 · 00:{{32+i*3}}:18</text></view><view class="between price-line"><view><text class="group-price"><i>{{2+i%2}}人团</i> ¥{{Math.round(item.price*.78)}}</text><text class="single">单买 ¥{{item.price}}</text></view><button @tap="join(item)">去拼团</button></view></view></view></view>
  </view>
</template>
<script setup>
import{products}from'../../data/mock';import{requireLogin}from'../../utils/shop';const open=id=>uni.navigateTo({url:`/pages/product/product?id=${id}`});const join=item=>{uni.setStorageSync('buy_now',[{...item,price:Math.round(item.price*.78),quantity:1,checked:true,subtitle:item.specs[0]+' · 拼团'}]);if(requireLogin('/pages/checkout/checkout?from=buy'))uni.navigateTo({url:'/pages/checkout/checkout?from=buy'})}
</script>
<style scoped>
.group-page{padding-bottom:50rpx}.group-hero{height:350rpx;background:linear-gradient(135deg,var(--accent-start),var(--accent-end));color:#fff;padding:56rpx 38rpx;box-sizing:border-box;position:relative;overflow:hidden}.group-en,.group-title,.group-copy{display:block;position:relative;z-index:2}.group-en{font-size:18rpx;letter-spacing:4rpx;opacity:.6}.group-title{font-size:46rpx;font-weight:700;margin-top:24rpx}.group-copy{font-size:23rpx;opacity:.75;margin-top:15rpx}.faces{position:absolute;right:35rpx;bottom:35rpx;display:flex}.faces text{width:76rpx;height:76rpx;line-height:76rpx;text-align:center;background:var(--accent-soft);color:var(--accent);border:5rpx solid var(--accent-end);border-radius:50%;margin-left:-18rpx;font-weight:700}.faces text:nth-child(2){background:var(--card);color:var(--ink)}.faces text:nth-child(3){background:var(--card);color:var(--accent)}.steps{display:flex;align-items:center;justify-content:center;background:var(--card);padding:28rpx 16rpx}.steps view{text-align:center}.steps view text{display:block;font-size:19rpx}.steps view text:first-child{width:42rpx;height:42rpx;line-height:42rpx;margin:0 auto 8rpx;border-radius:50%;background:var(--accent-soft)}.steps i{width:38rpx;height:1rpx;background:var(--line);margin:0 8rpx}.section-head{padding:50rpx 28rpx 24rpx;align-items:flex-end}.section-title,.section-en{display:block}.group-list{padding:0 28rpx}.group-item{display:flex;padding:20rpx;margin-bottom:20rpx}.group-art{width:235rpx;height:255rpx;border-radius:var(--card-radius);flex-shrink:0}.group-art .art-icon{font-size:78rpx}.people{position:absolute;left:13rpx;top:13rpx;background:var(--ink);color:#fff;border-radius:30rpx;padding:7rpx 12rpx;font-size:18rpx}.group-info{padding:6rpx 0 0 22rpx;flex:1;min-width:0}.item-title,.item-sub{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-title{font-weight:700}.item-sub{font-size:21rpx;color:var(--muted);margin-top:8rpx}.active-group{display:flex;align-items:center;margin-top:23rpx;font-size:19rpx;color:var(--accent)}.tiny-face{width:38rpx;height:38rpx;line-height:38rpx;text-align:center;border-radius:50%;background:var(--accent-soft);margin-right:8rpx}.price-line{margin-top:19rpx}.group-price,.single{display:block}.group-price{font-size:30rpx;color:var(--accent);font-weight:700}.group-price i{font-style:normal;font-size:17rpx;background:var(--accent-soft);padding:4rpx}.single{font-size:18rpx;color:var(--muted);margin-top:5rpx}.price-line button{margin:0;background:var(--accent);color:#fff;border-radius:var(--control-radius);font-size:21rpx;padding:0 22rpx}
</style>
